            while (rs.next()) {
                rooms.add(new Room(
                    rs.getInt("number"),
                    Room.RoomType.valueOf(rs.getString("type")),
                    rs.getInt("capacity"),
                    rs.getBigDecimal("nightly_rate")
                ));
            }
        }
        return rooms;
    }
}

