            pstmt.setString(17, reservation.getStatus().name());
            pstmt.setBigDecimal(18, reservation.getAmountPaid());

            ResultSet rs = pstmt.executeQuery();
            if (rs.next()) {
                reservation.setId(rs.getLong("id"));
            }
        }
        return reservation;
