            pstmt.setInt(13, reservation.getNights());
            pstmt.setBigDecimal(14, reservation.getSubtotal());
            pstmt.setBigDecimal(15, reservation.getDiscount());
            pstmt.setBigDecimal(16, reservation.getTotal());
